package cat.plou.radar

import java.util.Base64

/** Valor dBZ correspondiente al índice 0 de cada rampa. */
const val DBZ_MIN = -32

/** Valor dBZ correspondiente al último índice de cada rampa. */
const val DBZ_MAX = 95

/**
 * Esquemas de color que acepta el parámetro `color` de la API de teselas.
 * `rain` y `snow` son 128 colores RGBA (un byte por canal) por cada dBZ.
 */
enum class ColorScheme(val id: Int, val label: String, rainB64: String, snowB64: String) {
    BLACK_AND_WHITE(0, "Blanco y negro",
        "",
        ""),
    ORIGINAL(1, "Original",
        "",
        ""),
    UNIVERSAL_BLUE(2, "Azul universal",
        "",
        ""),
    TITAN(3, "Titan",
        "",
        ""),
    TWC(4, "The Weather Channel",
        "",
        ""),
    METEORED(5, "Meteored",
        "",
        ""),
    NEXRAD(6, "NEXRAD nivel III",
        "",
        ""),
    RAINBOW(7, "Arcoíris (Selex SI)",
        "",
        ""),
    DARK_SKY(8, "Dark Sky",
        "",
        ""),
    ;

    val rain: ByteArray = Base64.getDecoder().decode(rainB64)
    val snow: ByteArray = Base64.getDecoder().decode(snowB64)

    companion object {
        fun byId(id: Int): ColorScheme = entries.firstOrNull { it.id == id } ?: UNIVERSAL_BLUE
    }
}
